# 2. Analyser le HTML
soup = BeautifulSoup(html_content, 'html.parser')

# 3. Préparer l'en-tête du tableau Markdown
md_output = "| Description | Nom du fichier | Taille | Lien de téléchargement |\n"
md_output += "| :--- | :--- | :--- | :--- |\n"

# 4. Trouver toutes les lignes
rows = soup.find_all('div', class_='Files__row___Qus4C')

# 5. Boucler sur chaque ligne
for row in rows:
    # On ignore la ligne d'en-tête du tableau HTML
    if row.find('div', class_='Files__descriptionColumn___oh9UC'):
        continue

    desc_tag = row.find('div', class_='Files__description___UFFq_')
    description = desc_tag.text.strip() if desc_tag and desc_tag.text.strip() else "-"
    # Échapper les pipes '|' dans la description pour ne pas casser le tableau MD
    description = description.replace('|', '\\|')

    title_tag = row.find('div', class_='Files__title___KNZUT')
    filename = title_tag.text.strip() if title_tag else ""

    size_tag = row.find('div', class_='Files__filesize___gcVxZ')
    filesize = size_tag.text.strip() if size_tag else ""

    link_tag = row.find('a')
    link = link_tag['href'] if link_tag else ""

    # 6. Formater la ligne en Markdown
    if filename:
        md_link = f"[{filename}]({link})"
        md_output += f"| {description} | `{filename}` | {filesize} | {md_link} |\n"

# 7. Afficher le résultat final
#print(md_output)

with open("data_files_links.md", "w") as f:
    f.write(md_output)